mapper.select:
select id, api_code, cell, marketing_time, push_status, status, create_date
from b_wuba_submit_conversion_data
where api_code = #{apiCode}
    and create_date = #{createDate}
    and status = #{status}
    and push_status = #{pushStatus}
    and is_deleted =0
limit #{pageSize}

select id, api_code, cell, marketing_time, push_status, status, user_type, create_date
from b_wuba_submit_conversion_data
where api_code = #{apiCode}
  and  marketing_time >= #{marketingTimeStart} and marketing_time < #{marketingTimeEnd} 
  and status = #{status}
  and push_status = #{pushStatus}
  and user_type = #{userType}
  and is_deleted =0
limit #{pageSize}

select id, api_code, cell, marketing_time, push_status, status, create_date
from b_wuba_submit_conversion_data
where api_code = #{apiCode}
    and  marketing_time >= #{marketingTimeStart} and marketing_time < #{marketingTimeEnd} 
    and is_deleted =0

        and  id > #{indexId} 

order by id asc limit #{pageSize}

select a.id, a.cell, b.marketing_time
from b_wuba_submit_conversion_data_log a
left join b_wuba_submit_conversion_data b on a.data_id =b.id
where a.api_code = #{apiCode}
  and  a.create_time >= #{pushTimeStart} and a.create_time < #{pushTimeEnd} 

    and  a.id > #{indexId} 

order by a.id asc limit #{pageSize}
